class MTPDmessages_emojiGameDiceInfo(
    val vgame_hash: String,
    val vprev_stake: Long,
    val vcurrent_streak: Int,
    val vparams: List<Int>,
    val vplays_left: Int? = null,
) : MTPmessages_EmojiGameInfo {
    override val constructorId: Int get() = CONSTRUCTOR
    override fun serializeBody(w: TlWriter) {
        w.int((if (vplays_left != null) 1 else 0))
        w.string(vgame_hash)
        w.long(vprev_stake)
        w.int(vcurrent_streak)
        w.vector(vparams) { w.int(it) }
        vplays_left?.let { w.int(it) }
    }
    companion object {
        const val CONSTRUCTOR: Int = 0x44e56023.toInt()
        fun read(r: TlReader): MTPDmessages_emojiGameDiceInfo {
            val _flags = r.int()
            val vgame_hash = r.string()
            val vprev_stake = r.long()
            val vcurrent_streak = r.int()
            val vparams = r.vector { r.int() }
            val vplays_left = if ((_flags and 1) != 0) r.int() else null
            return MTPDmessages_emojiGameDiceInfo(vgame_hash, vprev_stake, vcurrent_streak, vparams, vplays_left)
        }
    }
}

